/** Mask of @p width bits starting at bit @p lsb of a 32-bit word. */
#define YT921X_MASK(lsb, width) \
	((uint32_t)((UINT64_C(1) << (width)) - 1u) << (lsb))
/** Extract field F (a name without the _M or _S suffix) from a register value. */
#define YT921X_FGET(val, F) (((uint32_t)(val) & F##_M) >> F##_S)
/** Shift a value into the position of field F. */
#define YT921X_FPREP(F, x) (((uint32_t)(x) << F##_S) & F##_M)
/** Extract element i of array field F from a register value. */
#define YT921X_FGET_AT(val, F, i) (((uint32_t)(val) & F##_M(i)) >> F##_S(i))
/** Shift a value into the position of element i of array field F. */
#define YT921X_FPREP_AT(F, i, x) (((uint32_t)(x) << F##_S(i)) & F##_M(i))

/** Read a field of up to 64 bits from a register held as 32-bit words. */
static inline uint64_t yt921x_bits_get(const uint32_t *words, unsigned int lsb,
				      unsigned int width)
{
	uint64_t v = 0;

	for (unsigned int i = 0; i < width; i++) {
		unsigned int b = lsb + i;

		v |= (uint64_t)((words[b / 32u] >> (b % 32u)) & 1u) << i;
	}
	return v;
}

/** Write a field of up to 64 bits into a register held as 32-bit words. */
static inline void yt921x_bits_set(uint32_t *words, unsigned int lsb,
				   unsigned int width, uint64_t value)
{
	for (unsigned int i = 0; i < width; i++) {
		unsigned int b = lsb + i;
		uint32_t bit = UINT32_C(1) << (b % 32u);

		if ((value >> i) & 1u)
			words[b / 32u] |= bit;
		else
			words[b / 32u] &= ~bit;
	}
}

