#define YT921X_MIB_TX_BROADCAST 0x54u
/** Pause frames sent (32 bits). */
#define YT921X_MIB_TX_PAUSE 0x58u
/** Multicast frames sent (32 bits). */
#define YT921X_MIB_TX_MULTICAST 0x5cu
/** Frames sent shorter than 64 bytes (32 bits). */
#define YT921X_MIB_TX_UNDERSIZE_ERR 0x60u
/** Frames sent with a length of 64 bytes (32 bits). */
#define YT921X_MIB_TX_PKT_SZ_64 0x64u
/** Frames sent with a length of 65 to 127 bytes (32 bits). */
#define YT921X_MIB_TX_PKT_SZ_65_TO_127 0x68u
/** Frames sent with a length of 128 to 255 bytes (32 bits). */
#define YT921X_MIB_TX_PKT_SZ_128_TO_255 0x6cu
/** Frames sent with a length of 256 to 511 bytes (32 bits). */
#define YT921X_MIB_TX_PKT_SZ_256_TO_511 0x70u
/** Frames sent with a length of 512 to 1023 bytes (32 bits). */
#define YT921X_MIB_TX_PKT_SZ_512_TO_1023 0x74u
/** Frames sent with a length of 1024 to 1518 bytes (32 bits). */
#define YT921X_MIB_TX_PKT_SZ_1024_TO_1518 0x78u
/** Frames sent longer than 1518 bytes (32 bits). */
#define YT921X_MIB_TX_PKT_SZ_1519_TO_MAX 0x7cu
/** Bytes sent in good frames (64 bits). */
#define YT921X_MIB_TX_GOOD_BYTES 0x84u
/** Collisions seen while sending (32 bits). */
#define YT921X_MIB_TX_COLLISION 0x8cu
/** Frames not sent after 16 collisions (32 bits). */
#define YT921X_MIB_TX_EXCESSIVE_COLLISION 0x90u
/** Frames sent after more than one collision (32 bits). */
#define YT921X_MIB_TX_MULTIPLE_COLLISION 0x94u
/** Frames sent after exactly one collision (32 bits). */
#define YT921X_MIB_TX_SINGLE_COLLISION 0x98u
/** Good frames sent (32 bits). */
#define YT921X_MIB_TX_PKT 0x9cu
/** Frames whose first transmit attempt was deferred (32 bits). */
#define YT921X_MIB_TX_DEFERRED 0xa0u
/** Collisions seen later than 512 bit times into a frame (32 bits). */
#define YT921X_MIB_TX_LATE_COLLISION 0xa4u
/** OAM frames received (32 bits). */
#define YT921X_MIB_RX_OAM 0xa8u
/** OAM frames sent (32 bits). */
#define YT921X_MIB_TX_OAM 0xacu

